#!/usr/bin/env python3
"""Bridge-inventory drift check (2026-11-10, REVIEW-2026-11-10-07 P1-4).

The inventory (docs/arch/bridge-inventory.md) is the no-bridges gate's
grandfather list: check_no_bridges.py grandfathers exactly what is
inventoried there. A stale inventory therefore either blesses phantoms
or lets a real bridge slip through un-inventoried — which is what
happened to B-4: it claimed "142 generated synth_*.go" while disk held
140, and its own "~24 authored, ~110 verbatim vendored" summed to ~134.

This script pins the inventory's numbers to disk truth and fails on
any mismatch, so the counts cannot silently drift again:

  - synth_frontend_total: files matching internal/frontend/synth_*.go
    (top level only; *_test.go included — they are part of the glob).
  - synth_frontend_generated: files listed in the Makefile
    GENERATED_SYNTH block. That block (and the run_gen_synth.py
    GENERATORS mapping, which must agree with it) is the definition
    of "generated" — file headers are NOT ground truth: only 1 of the
    18 generator outputs carries a "Generated by" header, and 5
    hand-maintained files carry "Code generated"/"DO NOT EDIT" inside
    their embedded upstream source.
  - synth_frontend_test: internal/frontend/synth_*_test.go files.
  - synth_frontend_hand: the remainder (total - generated - test).
  - synth_p3frontend: files matching
    internal/frontend/p3frontend/synth_*.go.
  - synthetic_sources_entries: keys of the syntheticSources map
    literal in internal/frontend/synth_machinery.go (B-3).

It also pins the named machinery the inventory describes by symbol
(existence, never line number — line numbers drift within days):
B-2 syncPrimitiveName, the B-3 predicate/overlay symbols, the B-5
GoX509 EC helpers, and the B-7 rtstack node files.

The pinned numbers live in ```inventory-pins fenced blocks in
docs/arch/bridge-inventory.md (one per section they pin). A retirement
that changes a count must update the pin in the same change — the
script fails loudly until it does.

Usage:
  python3 .github/scripts/check_bridge_inventory.py [root]
Run from the repo root (or pass the root). Wired into `make check`
and CI (build-and-check job, next to the no-bridges check).

The check NEVER passes vacuously: a missing inventory, a missing
pins block, a missing pins key, or an unparsable generator mapping
fails loudly instead of skipping.
"""

import glob
import os
import re
import sys

# (relative path, needle, label) — the named machinery the inventory
# describes. Existence only; line numbers are not pinned.
SYMBOL_CHECKS = [
    ("internal/backend/truffle/src/main/java/graalgo/frontend/NodeFactory.java",
     "syncPrimitiveName", "B-2 syncPrimitiveName"),
    ("internal/frontend/synth_machinery.go",
     "func isMultiResultSynthetic(", "B-3 isMultiResultSynthetic"),
    ("internal/frontend/synth_machinery.go",
     "func multiResultSyntheticError(", "B-3 multiResultSyntheticError"),
    ("internal/frontend/synth_machinery.go",
     "func isTimeIntrinsicFunc(", "B-3 isTimeIntrinsicFunc"),
    ("internal/frontend/synth_machinery.go",
     "func isMathIntrinsicFunc(", "B-3 isMathIntrinsicFunc"),
    ("internal/frontend/synth_machinery.go",
     "func isAliasIntrinsicFunc(", "B-3 isAliasIntrinsicFunc"),
    ("internal/frontend/synth_machinery.go",
     "func isAbiFuncPCIntrinsicFunc(", "B-3 isAbiFuncPCIntrinsicFunc"),
    ("internal/frontend/synth_reflect.go",
     "func isReflectIntrinsicFunc(", "B-3 isReflectIntrinsicFunc"),
    ("internal/frontend/diskimport.go",
     "overlayImporter", "B-3 overlayImporter"),
    ("internal/frontend/diskimport.go",
     "func resolvePkgTree(", "B-3 resolvePkgTree"),
    ("internal/frontend/export.go",
     '"syncop"', 'B-3 "syncop" wire node'),
    ("internal/frontend/mrdesugar_m5.go",
     '"runtimecaller"', 'B-3 "runtimecaller" wire node'),
    ("internal/backend/interop/src/main/java/graalgo/p3x509/GoX509.java",
     "scalarMultiply", "B-5 GoX509.scalarMultiply"),
    ("internal/backend/interop/src/main/java/graalgo/p3x509/GoX509.java",
     "ecAdd", "B-5 GoX509.ecAdd"),
    ("internal/backend/interop/src/main/java/graalgo/p3x509/GoX509.java",
     "ecDouble", "B-5 GoX509.ecDouble"),
]

# B-7 rtstack node files (the inventory's parenthetical list is the
# full set: Callers/CallersFrames/Func surface).
RTSTACK_FILES = [
    "RuntimeCallerNode.java",
    "RuntimeCallersNode.java",
    "RuntimeCallersFramesNode.java",
    "RuntimeFramesNextNode.java",
    "RuntimeFuncEntryNode.java",
    "RuntimeFuncFileLineNode.java",
    "RuntimeFuncForPCNode.java",
    "RuntimeFuncNameNode.java",
    "RtStack.java",
]

REQUIRED_PINS = (
    "synth_frontend_total",
    "synth_frontend_generated",
    "synth_frontend_test",
    "synth_frontend_hand",
    "synth_p3frontend",
    "synthetic_sources_entries",
)


def read_pins(root):
    """Parse every ```inventory-pins block in the inventory.

    Returns (pins dict, errors list). Fails loudly on a missing
    inventory, a missing block, a missing key, a duplicate key, or a
    non-integer value — never a vacuous pass.
    """
    path = os.path.join(root, "docs/arch/bridge-inventory.md")
    errors = []
    try:
        with open(path, encoding="utf-8") as f:
            text = f.read()
    except OSError as e:
        return {}, [f"cannot read inventory {path}: {e}"]
    blocks = re.findall(r"^```inventory-pins\n(.*?)^```", text, re.S | re.M)
    if not blocks:
        return {}, ["no ```inventory-pins block in docs/arch/bridge-inventory.md "
                    "(refusing to pass vacuously)"]
    pins = {}
    for block in blocks:
        for lineno, line in enumerate(block.split("\n"), 1):
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            m = re.match(r"([a-z0-9_]+)\s*=\s*(\d+)\s*$", line)
            if not m:
                errors.append(f"unparsable pin line in inventory-pins block: "
                              f"{line!r}")
                continue
            key, value = m.group(1), int(m.group(2))
            if key in pins:
                errors.append(f"duplicate pin {key!r} in inventory-pins blocks")
            pins[key] = value
    for key in REQUIRED_PINS:
        if key not in pins:
            errors.append(f"missing required pin {key!r} in "
                          f"docs/arch/bridge-inventory.md")
    return pins, errors


def makefile_generated(root):
    """Files listed in the root Makefile GENERATED_SYNTH block."""
    path = os.path.join(root, "Makefile")
    try:
        with open(path, encoding="utf-8") as f:
            lines = f.read().split("\n")
    except OSError as e:
        return None, [f"cannot read Makefile: {e}"]
    files = []
    in_block = False
    for line in lines:
        if line.startswith("GENERATED_SYNTH :="):
            in_block = True
            continue
        if in_block:
            files += re.findall(r"internal/frontend/(synth_[A-Za-z0-9_]+\.go)",
                                line)
            if not line.rstrip().endswith("\\"):
                break
    if not in_block:
        return None, ["no GENERATED_SYNTH block in Makefile"]
    return sorted(set(files)), []


def runner_generated(root):
    """Files listed in run_gen_synth.py's GENERATORS mapping."""
    path = os.path.join(root, "internal/frontend/run_gen_synth.py")
    try:
        with open(path, encoding="utf-8") as f:
            text = f.read()
    except OSError as e:
        return None, [f"cannot read run_gen_synth.py: {e}"]
    m = re.search(r"GENERATORS\s*=\s*\[(.*?)\n\]", text, re.S)
    if not m:
        return None, ["no GENERATORS mapping in "
                      "internal/frontend/run_gen_synth.py"]
    files = sorted(set(re.findall(r'"(synth_[A-Za-z0-9_]+\.go)"', m.group(1))))
    return files, []


def synthetic_sources_entries(root):
    """Keys of the syntheticSources map literal in synth_machinery.go."""
    path = os.path.join(root, "internal/frontend/synth_machinery.go")
    try:
        with open(path, encoding="utf-8") as f:
            lines = f.read().split("\n")
    except OSError as e:
        return None, [f"cannot read synth_machinery.go: {e}"]
    start = None
    for i, line in enumerate(lines):
        if re.match(r"var syntheticSources\s*=\s*map\[string\]string\{",
                    line):
            start = i
            break
    if start is None:
        return None, ["no syntheticSources map literal in "
                      "internal/frontend/synth_machinery.go"]
    keys = []
    for line in lines[start + 1:]:
        if line == "}":
            break
        m = re.match(r'\s*"([^"]+)"\s*:', line)
        if m:
            keys.append(m.group(1))
    else:
        return None, ["syntheticSources map literal never closes in "
                      "internal/frontend/synth_machinery.go"]
    if len(keys) != len(set(keys)):
        return None, ["duplicate keys in syntheticSources map literal"]
    return keys, []


def disk_counts(root):
    """Count the synth files and generator mappings on disk.

    Returns (counts dict, errors list).
    """
    errors = []
    frontend = sorted(
        os.path.basename(p)
        for p in glob.glob(os.path.join(root, "internal/frontend",
                                       "synth_*.go"))
        if os.path.isfile(p))
    if not frontend:
        errors.append("no internal/frontend/synth_*.go files found")
    p3 = sorted(
        os.path.basename(p)
        for p in glob.glob(os.path.join(root, "internal/frontend",
                                       "p3frontend", "synth_*.go"))
        if os.path.isfile(p))
    if not p3:
        errors.append("no internal/frontend/p3frontend/synth_*.go files found")
    test = sorted(f for f in frontend if f.endswith("_test.go"))
    generated_mk, errs = makefile_generated(root)
    errors += errs
    generated_run, errs = runner_generated(root)
    errors += errs
    if generated_mk is not None and generated_run is not None:
        if generated_mk != generated_run:
            errors.append(
                "Makefile GENERATED_SYNTH != run_gen_synth.py GENERATORS: "
                f"only in Makefile: {sorted(set(generated_mk) - set(generated_run))}; "
                f"only in run_gen_synth.py: "
                f"{sorted(set(generated_run) - set(generated_mk))}")
        missing = [f for f in generated_mk if f not in frontend]
        if missing:
            errors.append("GENERATED_SYNTH files missing on disk: "
                          + ", ".join(missing))
    generated = generated_mk if generated_mk is not None else []
    hand = sorted(set(frontend) - set(generated) - set(test))
    counts = {
        "synth_frontend_total": len(frontend),
        "synth_frontend_generated": len(generated),
        "synth_frontend_test": len(test),
        "synth_frontend_hand": len(hand),
        "synth_p3frontend": len(p3),
    }
    sources, errs = synthetic_sources_entries(root)
    errors += errs
    counts["synthetic_sources_entries"] = len(sources) if sources else 0
    return counts, errors


def check_symbols(root):
    """Verify the named bridge machinery still exists (by symbol)."""
    errors = []
    for rel, needle, label in SYMBOL_CHECKS:
        path = os.path.join(root, rel)
        try:
            with open(path, encoding="utf-8", errors="replace") as f:
                text = f.read()
        except OSError as e:
            errors.append(f"{label}: cannot read {rel}: {e}")
            continue
        if needle not in text:
            errors.append(f"{label}: {needle!r} not found in {rel} "
                          f"(renamed, moved, or retired without updating "
                          f"docs/arch/bridge-inventory.md)")
    rtstack = os.path.join(root, "internal/backend/interop/src/main/java",
                           "graalgo/rtstack")
    for name in RTSTACK_FILES:
        if not os.path.isfile(os.path.join(rtstack, name)):
            errors.append(f"B-7 rtstack file missing on disk: {name}")
    return errors


def check_inventory(root):
    """Full check. Returns (errors list, counts dict, pins dict)."""
    errors = []
    pins, errs = read_pins(root)
    errors += errs
    counts, errs = disk_counts(root)
    errors += errs
    errors += check_symbols(root)
    for key in REQUIRED_PINS:
        if key in pins and key in counts and pins[key] != counts[key]:
            errors.append(
                f"{key}: inventory says {pins[key]}, disk has {counts[key]} "
                f"— update the ```inventory-pins block in "
                f"docs/arch/bridge-inventory.md in the same change")
    if ("synth_frontend_total" in counts
            and "synth_frontend_generated" in counts
            and "synth_frontend_test" in counts
            and "synth_frontend_hand" in counts):
        split = (counts["synth_frontend_generated"]
                 + counts["synth_frontend_test"]
                 + counts["synth_frontend_hand"])
        if split != counts["synth_frontend_total"]:
            errors.append(
                f"synth split does not add up: generated "
                f"({counts['synth_frontend_generated']}) + test "
                f"({counts['synth_frontend_test']}) + hand "
                f"({counts['synth_frontend_hand']}) = {split} != total "
                f"({counts['synth_frontend_total']})")
    return errors, counts, pins


def main():
    root = os.path.abspath(sys.argv[1]) if len(sys.argv) > 1 else \
        os.path.dirname(os.path.dirname(os.path.dirname(
            os.path.abspath(__file__))))
    errors, counts, pins = check_inventory(root)
    if errors:
        print("BRIDGE-INVENTORY CHECK FAILED:")
        print()
        for e in errors:
            print(f"  ✗ {e}")
        print()
        print("The inventory is the no-bridges gate's grandfather list — "
              "a stale count blesses phantoms or lets a real bridge slip "
              "through un-inventoried. Update the pins in "
              "docs/arch/bridge-inventory.md (same change as the "
              "retirement/addition).")
        return 1
    print("Bridge-inventory check passed: "
          f"frontend synth total {counts['synth_frontend_total']} "
          f"({counts['synth_frontend_generated']} generated + "
          f"{counts['synth_frontend_test']} test + "
          f"{counts['synth_frontend_hand']} hand-maintained), "
          f"p3frontend mirrors {counts['synth_p3frontend']}, "
          f"syntheticSources entries "
          f"{counts['synthetic_sources_entries']}.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
